1	import { db } from "@/lib/db";
2	import { applySeo, robotsTxt, siteBaseUrl, sitemapXml } from "@/lib/site-seo";
3	
4	export const dynamic = "force-dynamic";
5	
6	const MIME: Record<string, string> = {
7	  html: "text/html; charset=utf-8",
8	  css: "text/css; charset=utf-8",
9	  js: "text/javascript; charset=utf-8",
10	  map: "application/json",
11	  json: "application/json",
12	  svg: "image/svg+xml",
13	  txt: "text/plain; charset=utf-8",
14	  // xml is required for sitemap.xml — without it a sitemap served as
15	  // application/octet-stream is ignored by crawlers.
16	  xml: "application/xml; charset=utf-8",
17	  ico: "image/x-icon",
18	  png: "image/png",
19	  jpg: "image/jpeg",
20	  jpeg: "image/jpeg",
21	  webp: "image/webp",
22	  woff2: "font/woff2",
23	};
24	
25	// Locks generated pages down to nothing but themselves — matches the "no
26	// external requests" contract the builder is prompted with, so a page that
27	// somehow got a remote script past the agent still can't execute it.
28	const SANDBOX_CSP =
29	  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'";
30	
31	export async function GET(
32	  req: Request,
33	  { params }: { params: Promise<{ slug: string; path?: string[] }> },
34	) {
35	  const { slug, path } = await params;
36	  const filePath = path && path.length > 0 ? path.join("/") : "index.html";
37	
38	  const project = await db.project.findUnique({ where: { slug } });
39	  if (!project || !project.publishedAt) {
40	    return new Response("Site not found.", { status: 404 });
41	  }
42	
43	  const baseUrl = siteBaseUrl(req, slug);
44	  const seoHeaders = {
45	    "Content-Security-Policy": SANDBOX_CSP,
46	    "Cache-Control": "public, max-age=60",
47	  };
48	
49	  // robots.txt and sitemap.xml are generated, not stored — they depend on the
50	  // visitor-facing host (which differs between the branded subdomain and the
51	  // staging path form), so a file baked at build time would be wrong on one of
52	  // them. A site that ships its own copy still wins: we only synthesise these
53	  // when the project has no such file.
54	  if (filePath === "robots.txt" || filePath === "sitemap.xml") {
55	    const own = await db.projectFile.findFirst({
56	      where: { projectId: project.id, path: filePath, published: true, kind: "build" },
57	    });
58	    if (!own) {
59	      if (filePath === "robots.txt") {
60	        return new Response(robotsTxt(baseUrl), {
61	          headers: { ...seoHeaders, "Content-Type": MIME.txt },
62	        });
63	      }
64	      const pages = await db.projectFile.findMany({
65	        where: { projectId: project.id, published: true, kind: "build", path: { endsWith: ".html" } },
66	        select: { path: true },
67	      });
68	      return new Response(
69	        sitemapXml(baseUrl, pages.map((p) => p.path), project.publishedAt ?? undefined),
70	        { headers: { ...seoHeaders, "Content-Type": MIME.xml } },
71	      );
72	    }
73	  }
74	
75	  const file = await db.projectFile.findFirst({
76	    where: { projectId: project.id, path: filePath, published: true, kind: "build" },
77	  });
78	  if (!file) {
79	    return new Response("Not found.", { status: 404 });
80	  }
81	
82	  const ext = filePath.split(".").pop() ?? "";
83	
84	  // Backstop so no site can ship with the foundation's placeholder <title>.
85	  // Only fills gaps — anything the builder wrote itself is preserved.
86	  const body =
87	    ext === "html" ? applySeo(file.content, { projectName: project.name, baseUrl }) : file.content;
88	
89	  return new Response(body, {
90	    headers: { ...seoHeaders, "Content-Type": MIME[ext] ?? "application/octet-stream" },
91	  });
92	}
